public class NDXEldas extends common
{
}

Method.Source:
/// <summary>
/// PaffH 08.11.21
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_update">boolean</param>
/// <returns>NDXEldas</returns>
public static NDXEldas find(ItemId _itemId, boolean _update = false)
{
    InventTable inventTable;
    NDXEldas nDXEldas;
    nDXEldas.selectForUpdate(_update);
    select firstonly nDXEldas
        exists join inventTable where inventTable.ItemId == nDXEldas.ItemId
            && inventTable.ItemId == _itemId;

    return nDXEldas;
}

/// <summary>
/// PaffH 09.11.21
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(NDXEldas, EldasEMNr) :
            this.EldasEMNrSearch = NDXEldas::SetSearchEldasEMNr(this.EldasEMNr);
            this.UpdatedUTC = DateTimeUtil::utcNow();
            break;
        case fieldNum(NDXEldas, EldasENo) :
            this.EldasENoSearch = NDXEldas::SetSearchEldasENo(this.EldasENo);
            this.UpdatedUTC = DateTimeUtil::utcNow();
            break;
    }
}

/// <summary>
/// PaffH 09.11.21
/// </summary>
/// <param name = "_nDXEldasNrBase">NDXEldasNrBase</param>
/// <returns>ELDAS number whitespace adjusted and in upper</returns>
public static NDXEldasNrBase RemoveCharForSearch(NDXEldasNrBase _nDXEldasNrBase)
{
    const str removeChars = @' /';
    return strUpr(strRem(_nDXEldasNrBase, removeChars));
}

/// <summary>
/// PaffH 09.11.21
/// </summary>
/// <param name = "_nDXEldasEMNr">NDXEldasEMNr</param>
/// <returns>NDXEldasNrBase</returns>
public static NDXEldasNrBase SetSearchEldasEMNr(NDXEldasEMNr _nDXEldasEMNr)
{
    return NDXEldas::RemoveCharForSearch(_nDXEldasEMNr);
}

/// <summary>
/// PaffH 09.11.21
/// </summary>
/// <param name = "_nDXEldasENo">NDXEldasENo</param>
/// <returns>NDXEldasNrBase</returns>
public static NDXEldasNrBase SetSearchEldasENo(NDXEldasENo _nDXEldasENo)
{
    return NDXEldas::RemoveCharForSearch(_nDXEldasENo);
}

/// <summary>
/// PaffH 09.11.21
/// initialize search values
/// </summary>
public static void initSearchELDAS()
{
    NDXEldas nDXEldas;
    NDXUpdatedUTCDateTime updatedUTC = DateTimeUtil::utcNow();

    ttsbegin;

    update_recordset nDXEldas setting
        EldasEMNrSearch = NDXEldas::SetSearchEldasEMNr(nDXEldas.EldasEMNr),
        EldasENoSearch = NDXEldas::SetSearchEldasENo(nDXEldas.EldasENo),
        UpdatedUTC = updatedUTC
        where nDXEldas.EldasEMNr != ''
        && nDXEldas.EldasENo != '';
    update_recordset nDXEldas setting
        EldasEMNrSearch = NDXEldas::SetSearchEldasEMNr(nDXEldas.EldasEMNr),
        UpdatedUTC = updatedUTC
        where nDXEldas.EldasEMNr != ''
        && nDXEldas.EldasENo == '';
    update_recordset nDXEldas setting
        EldasENoSearch = NDXEldas::SetSearchEldasENo(nDXEldas.EldasENo),
        UpdatedUTC = updatedUTC
        where nDXEldas.EldasEMNr == ''
        && nDXEldas.EldasENo != '';
    update_recordset nDXEldas setting
        EldasEMNrSearch = '',
        EldasENoSearch = '',
        UpdatedUTC = updatedUTC
        where (nDXEldas.EldasEMNr != '' || nDXEldas.EldasENo != '')
            && (nDXEldas.EldasEMNrSearch != '' || nDXEldas.EldasENoSearch != '')
            && nDXEldas.UpdatedUTC != UpdatedUTC;
    ttscommit;
}
